<div class="toolbar"><span class="grow"><?= $w['status'] === 'live' ? badge('Live now', 'live') : badge(ucfirst($w['status']), 'blue') ?> <span class="muted small"><?= e(fmt_dt($w['start_at'])) ?> · <?= e(minutes_label((int) $w['duration_min'])) ?> · <?= $w['access'] === 'public' ? 'Public link' : 'Registered attendees' ?></span></span>
<?php if (in_array($w['status'], ['scheduled', 'live'], true)): ?><a class="btn btn-primary btn-sm" href="/webinars/<?= e($w['slug']) ?>/room"><?= icon('video', 15) ?> Open host room</a><?php endif; ?><a class="btn btn-ghost btn-sm" href="/admin/webinars/<?= (int) $w['id'] ?>/edit">Edit</a><a class="btn btn-ghost btn-sm" target="_blank" href="/webinars/<?= e($w['slug']) ?>">Public page</a></div>
<div class="panel"><div class="panel-b small" style="display:flex;gap:10px;align-items:center;flex-wrap:wrap"><strong>Share:</strong><code><?= e(abs_url('/webinars/' . $w['slug'])) ?></code><button class="rowbtn" data-copy="<?= e(abs_url('/webinars/' . $w['slug'])) ?>"><?= icon('copy', 13) ?> Copy link</button></div></div>
<div class="stats"><div class="stat"><b><?= $stats['regs'] ?></b><span>Registered</span></div><div class="stat"><b><?= $stats['att'] ?></b><span>Attended</span></div><div class="stat"><b><?= $stats['avg'] ?> min</b><span>Average time in session</span></div><div class="stat"><b><?= $stats['rating'] ? number_format($stats['rating'], 1) : '—' ?></b><span>Feedback rating</span></div><div class="stat"><b><?= $stats['questions'] ?></b><span>Questions asked</span></div><?php if ($w['price'] > 0): ?><div class="stat"><b><?= e(money($stats['revenue'])) ?></b><span>Verified revenue</span></div><?php endif; ?></div>
<div class="two"><div class="panel"><div class="panel-h"><span>Registrants and attendance</span><a class="link" href="?export=csv">Export CSV</a></div><div class="table-wrap" style="border:0"><table class="t"><thead><tr><th>Person</th><th>Status</th><th>Role</th><th>Attended</th><th></th></tr></thead><tbody>
<?php foreach ($regs as $r): ?><tr><td><strong><?= e($r['name']) ?></strong><div class="muted xs"><?= e($r['email']) ?></div></td><td><?= badge($r['status'], ['registered' => 'green', 'pending_payment' => 'amber', 'removed' => 'red'][$r['status']] ?? '') ?></td><td><form method="post" action="/admin/webinars/<?= (int) $w['id'] ?>/regs"><?= csrf_field() ?><input type="hidden" name="rid" value="<?= (int) $r['id'] ?>"><?php if ($r['role'] === 'host'): ?>Host<?php else: ?><select name="action" onchange="this.form.submit()" style="padding:4px 6px;width:auto"><?php foreach (['attendee', 'panelist', 'cohost'] as $x) { echo '<option' . ($r['role'] === $x ? ' selected' : '') . '>' . $x . '</option>'; } ?></select><?php endif; ?></form></td>
<td class="small"><?= $r['attended'] ? '✓ ' . round($r['seconds_in'] / 60) . ' min' : '—' ?><?= $r['feedback_rating'] ? ' · ' . (int) $r['feedback_rating'] . '★' : '' ?></td>
<td class="tbl-actions"><?php if ($r['role'] !== 'host'): ?><form method="post" action="/admin/webinars/<?= (int) $w['id'] ?>/regs"><?= csrf_field() ?><input type="hidden" name="rid" value="<?= (int) $r['id'] ?>"><button class="rowbtn" name="action" value="resend">Resend link</button><?php if ($r['status'] === 'removed'): ?><button class="rowbtn" name="action" value="restore">Restore</button><?php else: ?><button class="rowbtn danger" name="action" value="remove" data-confirm="Cancel this registration?">Cancel</button><?php endif; ?></form><?php endif; ?></td></tr><?php endforeach; ?>
<?php if (!$regs): ?><tr><td colspan="5" class="center muted" style="padding:24px">No registrations yet.</td></tr><?php endif; ?></tbody></table></div></div>
<div><form class="panel" method="post" action="/admin/webinars/<?= (int) $w['id'] ?>/regs"><?= csrf_field() ?><input type="hidden" name="action" value="add"><div class="panel-h">Add a participant</div><div class="panel-b form"><?= a_in('Name', 'name', '', ['required' => true]) ?><?= a_in('Email', 'email', '', ['type' => 'email', 'required' => true]) ?><?= a_sel('Role', 'role', ['attendee' => 'Attendee', 'panelist' => 'Panelist (on camera)', 'cohost' => 'Co-host (on camera)'], 'attendee') ?><button class="btn btn-ghost btn-sm">Add and email link</button></div></form>
<?php if ($qa): ?><div class="panel"><div class="panel-h">Q&amp;A</div><div class="panel-b"><?php foreach ($qa as $q): ?><p class="small" style="margin:0 0 8px"><?= $q['answered'] ? '✅' : '❓' ?> <strong><?= e($q['name']) ?></strong> (<?= (int) $q['votes'] ?>▲): <?= e($q['body']) ?></p><?php endforeach; ?></div></div><?php endif; ?>
<?php foreach ($polls as $po): $tot = max(1, array_sum($po['counts'])); ?><div class="panel"><div class="panel-h">Poll: <?= e($po['question']) ?></div><div class="panel-b"><?php foreach ($po['opts'] as $i => $o): ?><div class="small" style="margin-bottom:8px"><?= e($o) ?> — <strong><?= (int) $po['counts'][$i] ?></strong><div class="progress"><i style="width:<?= round($po['counts'][$i] * 100 / $tot) ?>%"></i></div></div><?php endforeach; ?></div></div><?php endforeach; ?>
<?php if (is_super()): ?><form method="post" action="/admin/webinars/<?= (int) $w['id'] ?>/delete"><?= csrf_field() ?><button class="btn btn-ghost btn-xs" data-confirm="Delete this session and all its data?">Delete session</button></form><?php endif; ?></div></div>
